import narwhals as nw
import pandas as pd
import polars as pl
from functools import wraps

def narwhalify(func):
    @wraps(func)
    def wrapper(df):
        return func(nw.from_native(df)).to_native()
    return wrapper

@narwhalify
def add_total(df):
    return df.with_columns(
        total=nw.col("price") * nw.col("quantity")
    )

# Test with pandas
pdf = pd.DataFrame({"price": [10, 20, 30], "quantity": [2, 3, 4]})
print(add_total(pdf))
print()

# Test with polars
plf = pl.DataFrame({"price": [10, 20, 30], "quantity": [2, 3, 4]})
print(add_total(plf))
